# Count 4-connected neighbors for each 5 (including diagonals? No, just 4 directions)
def neighbor_count_grid(arr):
    result = []
    for r in range(len(arr)):
        row = []
        for c in range(len(arr[0])):
            if arr[r][c] == 5:
                count = 0
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(arr) and 0 <= nc < len(arr[0]):
                        if arr[nr][nc] == 5:
                            count += 1
                row.append(count)
            else:
                row.append(arr[r][c])
        result.append(row)
    return result

counts_4conn = neighbor_count_grid(grid)
print("4-connected neighbor counts for 5s:")
for row in counts_4conn:
    print(row)

# Count ALL 8-connected neighbors 
def neighbor_count_8conn(arr):
    result = []
    for r in range(len(arr)):
        row = []
        for c in range(len(arr[0])):
            if arr[r][c] == 5:
                count = 0
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        if dr != 0 or dc != 0:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < len(arr) and 0 <= nc < len(arr[0]):
                                if arr[nr][nc] == 5:
                                    count += 1
                row.append(count)
            else:
                row.append(arr[r][c])
        result.append(row)
    return result

counts_8conn = neighbor_count_8conn(grid)
print("\n8-connected neighbor counts for 5s:")
for row in counts_8conn:
    print(row)
